tokenized_state_machine!{ X {
    fields {
        #[sharding(variable)] pub counter: int,
        #[sharding(variable)] pub ticket_a: bool,
        #[sharding(variable)] pub ticket_b: bool,
    }
    init!{ initialize() {
        init counter = 0; init ticket_a = false; init ticket_b = false;
    } }
    transition!{ do_increment_a() {
        require(!pre.ticket_a);             // an unstamped ticket
        update counter = pre.counter + 1;
        update ticket_a = true;             // stamp it
    } }
    // do_increment_b is the same with ticket_b
    readonly!{ finalize() {
        require(pre.ticket_a); require(pre.ticket_b);
        assert(pre.counter == 2);
    } }
    #[invariant]
    pub fn main_inv(&self) -> bool {
        self.counter == (if self.ticket_a { 1 as int } else { 0 })
                      + (if self.ticket_b { 1 as int } else { 0 })
    }
    #[inductive(do_increment_a)]
    fn inc_a_preserves(pre: Self, post: Self) { }
    // plus the same lemma for initialize and do_increment_b
} }
